mod common;
use common::Json;
use std::panic::{catch_unwind, AssertUnwindSafe};

trait ToJ {
    fn j(&self) -> Json;
}
impl ToJ for i32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u8 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for i64 {
    fn j(&self) -> Json {
        Json::Int(*self)
    }
}
impl ToJ for bool {
    fn j(&self) -> Json {
        Json::Bool(*self)
    }
}
impl ToJ for String {
    fn j(&self) -> Json {
        Json::Str(self.clone())
    }
}
impl<T: ToJ> ToJ for Vec<T> {
    fn j(&self) -> Json {
        Json::Arr(self.iter().map(|x| x.j()).collect())
    }
}
impl<T: ToJ> ToJ for Option<T> {
    fn j(&self) -> Json {
        match self {
            Some(x) => x.j(),
            None => Json::Null,
        }
    }
}

fn call(f: &str, a: &[Json]) -> Option<Result<Json, ()>> {
    Some(match f {
        "fmt_clock" => Ok(ferry_slots::fmt_clock(a[0].int_()).j()),
        "parse_clock" => ferry_slots::parse_clock(a[0].str_()).map(|v| v.j()).map_err(|_| ()),
        "split_clock" => Ok(ferry_slots::split_clock(a[0].int_()).j()),
        "slot_index" => ferry_slots::slot_index(a[0].int_(), a[1].int_(), a[2].int_()).map(|v| v.j()).map_err(|_| ()),
        "next_departure" => ferry_slots::next_departure(a[0].int_(), a[1].int_(), a[2].int_()).map(|v| v.j()).map_err(|_| ()),
        "wait_minutes" => ferry_slots::wait_minutes(a[0].int_(), a[1].int_(), a[2].int_()).map(|v| v.j()).map_err(|_| ()),
        "align_down" => ferry_slots::align_down(a[0].int_(), a[1].int_()).map(|v| v.j()).map_err(|_| ()),
        _ => return None,
    })
}

#[test]
fn vectors() {
    let path = if std::path::Path::new("vectors/full.json").exists() { "vectors/full.json" } else { "vectors/examples.json" };
    let text = std::fs::read_to_string(path).expect("read vectors");
    let doc = common::parse(&text).expect("parse vectors");
    let cases = doc.get("cases").expect("cases").arr().clone();
    let mut bad: Vec<String> = Vec::new();
    for c in &cases {
        let f = c.get("fn").unwrap().str_().to_string();
        let args = c.get("args").unwrap().arr().clone();
        let label = format!("{}({})", f, args.iter().map(|a| a.to_string()).collect::<Vec<_>>().join(", "));
        let is_err = c.get("error").is_some();
        let res = catch_unwind(AssertUnwindSafe(|| call(&f, &args)));
        match res {
            Err(_) => bad.push(format!("{}: panic", label)),
            Ok(None) => bad.push(format!("missing function {}", f)),
            Ok(Some(Err(()))) => {
                if !is_err {
                    bad.push(format!("{}: unexpected error, want {}", label, c.get("want").unwrap()));
                }
            }
            Ok(Some(Ok(got))) => {
                if is_err {
                    bad.push(format!("{}: expected an error, got {}", label, got));
                } else if &got != c.get("want").unwrap() {
                    bad.push(format!("{}: want {}, got {}", label, c.get("want").unwrap(), got));
                }
            }
        }
    }
    if !bad.is_empty() {
        panic!("{} of {} vectors failed:\n  {}", bad.len(), cases.len(), bad.iter().take(8).cloned().collect::<Vec<_>>().join("\n  "));
    }
}
